const root=process.cwd();
await fs.access(path.join(root,'backend/server.mjs'));
await fs.access(path.join(root,'package.json'));
const backup=path.join(root,'respaldo-registro-portal-'+new Date().toISOString().replace(/[:.]/g,'-'));
async function safe(relative){let current=root;for(const part of relative.split('/')){current=path.join(current,part);try{if((await fs.lstat(current)).isSymbolicLink())throw Error('No se sustituye un enlace: '+relative);}catch(e){if(e.code!=='ENOENT')throw e;}}return current;}
const originals=new Map();
for(const relative of Object.keys(files)){
 const target=await safe(relative);
 try{const bytes=await fs.readFile(target);originals.set(relative,bytes);const dest=path.join(backup,relative);await fs.mkdir(path.dirname(dest),{recursive:true});await fs.writeFile(dest,bytes);}
 catch(e){if(e.code!=='ENOENT')throw e;originals.set(relative,null);}
}
for(const [name,bytes] of originals){
  if(bytes?.equals(Buffer.from(files[name])))continue;
  if(previous[name] && bytes && createHash('sha256').update(bytes).digest('hex')===previous[name])continue;
  if(!previous[name] && bytes===null)continue;
  throw Error('El archivo '+name+' difiere de la base 1.20.0. Revisa los cambios locales antes de actualizar.');
}
const written=[];
try{
 for(const [relative,text] of Object.entries(files)){const target=await safe(relative);await fs.mkdir(path.dirname(target),{recursive:true});written.push(relative);await fs.writeFile(target,text);}
}catch(error){
 for(const relative of written.reverse()){const target=await safe(relative),bytes=originals.get(relative);if(bytes===null)await fs.rm(target,{force:true});else await fs.writeFile(target,bytes);}
 throw error;
}
console.log('Registro de clientes actualizado. Respaldo: '+backup+'\nReinicia con npm start.');
